import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.6VU7PjNJ.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1784988047000}`),a={name:`guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><h2 id="about-minesweeper" tabindex="-1">About Minesweeper <a class="header-anchor" href="#about-minesweeper" aria-label="Permalink to “About Minesweeper”">​</a></h2><p><strong>Minesweeper — The Classic Game, Perfectly Made.</strong></p><p><img src="/screenshot-ipad-main.png" alt="Minesweeper running on iPad"></p><p>Rediscover the timeless puzzle game you love, refined for modern devices with smooth controls, clean visuals, and endless replayability. Whether you are a first-time player or a seasoned pro, this is the Minesweeper experience you have been waiting for.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to “Core Features”">​</a></h2><h3 id="💣-authentic-gameplay" tabindex="-1">💣 <strong>Authentic Gameplay</strong> <a class="header-anchor" href="#💣-authentic-gameplay" aria-label="Permalink to “💣 Authentic Gameplay”">​</a></h3><p>True to the original rules — tap to reveal tiles, long-press to flag mines, and use logic to clear the board safely.</p><h3 id="🎯-3-difficulty-levels" tabindex="-1">🎯 <strong>3 Difficulty Levels</strong> <a class="header-anchor" href="#🎯-3-difficulty-levels" aria-label="Permalink to “🎯 3 Difficulty Levels”">​</a></h3><p>Three preset difficulties with board sizes optimized per device:</p><table tabindex="0"><thead><tr><th>Level</th><th>iPhone</th><th>iPad</th><th>Mac</th></tr></thead><tbody><tr><td>Beginner</td><td>10×14 (14 mines)</td><td>16×16 (18 mines)</td><td>9×9 (10 mines)</td></tr><tr><td>Intermediate</td><td>14×22 (45 mines)</td><td>18×16 (55 mines)</td><td>16×16 (40 mines)</td></tr><tr><td>Expert</td><td>16×30 (99 mines)</td><td>18×24 (99 mines)</td><td>30×16 (99 mines)</td></tr></tbody></table><h3 id="📱-universal-app" tabindex="-1">📱 <strong>Universal App</strong> <a class="header-anchor" href="#📱-universal-app" aria-label="Permalink to “📱 Universal App”">​</a></h3><p>One purchase works on iPhone, iPad, and Mac. Native controls for each platform — touch gestures on iOS, mouse and keyboard on Mac.</p><p><img src="/screenshot-iphone-main.png" alt="Minesweeper on iPhone"></p><p><img src="/screenshot-mac-difficulty.png" alt="Minesweeper on Mac"></p><h3 id="🔇-clean-ad-free" tabindex="-1">🔇 <strong>Clean &amp; Ad-Free</strong> <a class="header-anchor" href="#🔇-clean-ad-free" aria-label="Permalink to “🔇 Clean &amp; Ad-Free”">​</a></h3><p>No interruptions, no pop-ups — just pure, focused gameplay.</p><h3 id="🌍-25-languages" tabindex="-1">🌍 <strong>25 Languages</strong> <a class="header-anchor" href="#🌍-25-languages" aria-label="Permalink to “🌍 25 Languages”">​</a></h3><p>Switch languages at runtime from Settings without restarting the app. Supports English, Chinese (Simplified &amp; Traditional), Japanese, Korean, French, German, Spanish, Italian, Russian, Portuguese, Dutch, Vietnamese, Thai, Hindi, Turkish, Greek, Finnish, Norwegian, Danish, Hungarian, Indonesian, Malay, Ukrainian, and German (Switzerland).</p><h3 id="🔊-sound-effects" tabindex="-1">🔊 <strong>Sound Effects</strong> <a class="header-anchor" href="#🔊-sound-effects" aria-label="Permalink to “🔊 Sound Effects”">​</a></h3><p>Subtle sound effects for clicks, flags, and game events — toggle on or off in Settings.</p><h3 id="⌨️-keyboard-shortcuts-mac" tabindex="-1">⌨️ <strong>Keyboard Shortcuts (Mac)</strong> <a class="header-anchor" href="#⌨️-keyboard-shortcuts-mac" aria-label="Permalink to “⌨️ Keyboard Shortcuts (Mac)”">​</a></h3><ul><li><code>⌘N</code> — New game</li><li><code>⌘1</code> / <code>⌘2</code> / <code>⌘3</code> — Beginner / Intermediate / Expert</li><li><code>⌘⇧R</code> — Reveal mines (practice mode)</li></ul><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to “System Requirements”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 15.0 or later</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) or later (Apple Silicon and Intel supported)</li><li><strong>Storage</strong>: ~50 MB</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to “Privacy”">​</a></h2><p>Minesweeper is offline-first. The game itself requires no network connection. No personal data is collected, no analytics, no tracking. The only network access is an optional &quot;More Apps&quot; section in Settings that fetches a list of sibling apps — this can be ignored and does not affect gameplay.</p><p>See the <a href="/guide/privacy.html">Privacy Policy</a> for details.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><p>If you&#39;re new to Minesweeper, start with the <a href="/guide/installation.html">Installation Guide</a> to get the app on your device.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};